Left_Wheel = Motor(Port.C, Direction.COUNTERCLOCKWISE)
Right_Wheel = Motor(Port.D, Direction.CLOCKWISE)
drive_base = DriveBase(Left_Wheel, Right_Wheel, 61, 152)
Front_Arm = Motor(Port.E, Direction.CLOCKWISE)
Back_Arm = Motor(Port.A, Direction.CLOCKWISE)
color_sensor = ColorSensor(Port.B)
color_sensor_2 = ColorSensor(Port.F)


# The main program starts here.
# Start
drive_base.use_gyro(True)
drive_base.settings(straight_speed=1001)
drive_base.straight(445)
drive_base.turn(50)
Front_Arm.run_angle(500, -235)
drive_base.straight(130)
Front_Arm.run_angle(500, 100)
drive_base.straight(-40)
drive_base.turn(50)
drive_base.straight(-20)
Front_Arm.run_angle(500, -100)
drive_base.straight(-50)
drive_base.turn(80)
drive_base.straight(-250)
Left_Wheel.run_angle(500, 370)
Back_Arm.run_angle(1000, -360)
drive_base.straight(-100)
Back_Arm.run_angle(500, 200)
drive_base.turn(-90)
drive_base.straight(600)
